@js:
var result = [];
var push = function(title, url, size) {
  result.push({
    title: title,
    url: url,
    style: {
      layout_flexGrow: 1,
      layout_flexBasisPercent: size
    }
  });
};
var api = '&channel=pc&app_name=zmh&version=1.0.0&timestamp=0&uid=0';
push('🏆 人气榜', 'https://v4api.zaimanhua.com/app/v1/comic/rank/list?tag_id=0&by_time=0&rank_type=0&page={{page}}&size=24' + api, 0.25);
push('💬 吐槽榜', 'https://v4api.zaimanhua.com/app/v1/comic/rank/list?tag_id=0&by_time=0&rank_type=1&page={{page}}&size=24' + api, 0.25);
push('⭐ 订阅榜', 'https://v4api.zaimanhua.com/app/v1/comic/rank/list?tag_id=0&by_time=0&rank_type=2&page={{page}}&size=24' + api, 0.25);
push('🆕 最新更新', 'https://v4api.zaimanhua.com/api/v1/comic2/update_list?page={{page}}&size=24' + api, 1);
push('🏷 按主题', null, 1);
var u = 'https://v4api.zaimanhua.com/app/v1/comic/filter/classify?channel=pc&app_name=zmh&version=1.0.0&timestamp=0&uid=0';
var d = JSON.parse(java.ajax(u)).data;
var ths = d.classifyList[0].list || [];
for (var i = 0; i < ths.length; i++) {
  var t = ths[i];
  if (t.tagId == 0) { continue; }
  push(t.tagName, 'https://v4api.zaimanhua.com/app/v1/comic/filter/list?theme=' + t.tagId + '&cate=0&status=0&zone=0&sortType=0&page={{page}}&size=24' + api, 0.25);
}
JSON.stringify(result);

