  var x = list[i];
  out.push(JSON.stringify({
    _name: x.name || x.title || '',
    _author: x.authors || '',
    _cover: x.cover || '',
    _kind: x.types || '',
    _intro: '状态：' + (x.status || '') + String.fromCharCode(10) + '更新：' + (x.last_update_chapter_name || ''),
    _last: x.last_update_chapter_name || '',
    _py: x.comic_py || x.comicId || ''
  }));
}
result = out;

