ruleToc.chapterList:
@js:
var d = (typeof result === 'string') ? JSON.parse(result) : result;
var ci = d.data.comicInfo;
var cid = ci.id;
var vols = ci.chapterList || [];
var arr = [];
for (var i = 0; i < vols.length; i++) {
  var chs = vols[i].data || [];
  for (var j = 0; j < chs.length; j++) {
    var ch = chs[j];
    var u = 'https://v4api.zaimanhua.com/api/v1/comic2/chapter/detail?comic_id=' + cid + '&chapter_id=' + ch.chapter_id + '&channel=pc&app_name=zmh&version=1.0.0&timestamp=0&uid=0';
    arr.push({name: ch.chapter_title, order: ch.chapter_order, url: u});
  }
}
arr.sort(function(a, b) { return (a.order || 0) - (b.order || 0); });
var out = [];
for (var k = 0; k < arr.length; k++) { out.push(JSON.stringify({name: arr[k].name, url: arr[k].url})); }
out;
